window.SERVIZI = {"Q109536065":{"s":"La General Directorate of Intelligence è il servizio di intelligence e sicurezza nazionale dell'Emirato islamico dell'Afghanistan, che fornisce informazioni su questioni interne ed estere al leader talebano Akhundzada.","t":"General Directorate of Intelligence","u":"https://en.wikipedia.org/wiki/General_Directorate_of_Intelligence","d":"2026-11-20","l":"en"},"Q3302652":{"s":"Lo Shërbimi Informativ Shtetëror (SHISH) è l'agenzia di intelligence per la sicurezza interna dell'Albania, con compiti di informazione, sicurezza e controspionaggio.","t":"Shërbimi Informativ Shtetëror","u":"https://it.wikipedia.org/wiki/Sh%C3%ABrbimi_Informativ_Shtet%C3%ABror","d":"2026-11-20","l":"it"},"Q285381":{"s":"La Al-Mukhabarat al-'Amma, Presidenza Generale dell'Intelligence, è la principale agenzia di intelligence dell'Arabia Saudita, un ente amministrativo con una propria struttura organizzativa e una serie di obiettivi definiti.","t":"Al-Mukhabarat al-'Amma","u":"https://it.wikipedia.org/wiki/Al-Mukhabarat_al-%27Amma","d":"2026-11-20","l":"it"},"Q33127804":{"s":"La Presidency of State Security è un organismo saudita creato il 20 luglio 2017 unendo i servizi antiterrorismo e di intelligence interna, sotto il controllo del re, con competenza su tutte le questioni di sicurezza dello Stato.","t":"Presidency of State Security","u":"https://en.wikipedia.org/wiki/Presidency_of_State_Security","d":"2026-11-20","l":"en"},"Q6173149":{"s":"La Jefatura de Inteligencia del Estado Mayor Conjunto (J-2) è un'agenzia federale argentina che controlla tutti i servizi di intelligence militare.","t":"Jefatura de Inteligencia del Estado Mayor Conjunto de las Fuerzas Armadas","u":"https://en.wikipedia.org/wiki/Jefatura_de_Inteligencia_del_Estado_Mayor_Conjunto_de_las_Fuerzas_Armadas","d":"2026-11-20","l":"en"},"Q7455862":{"s":"Il Servicio de Inteligencia Naval è l'agenzia di intelligence della Marina argentina, parte della J-2 e dello Stato Maggiore della Marina, con compiti di raccolta di informazioni navali rilevanti per l'Argentina.","t":"Servicio de Inteligencia Naval (Argentina)","u":"https://en.wikipedia.org/wiki/Servicio_de_Inteligencia_Naval_(Argentina)","d":"2026-11-20","l":"en"},"Q5062090":{"s":"La Central de Inteligencia Militar (CIM) è un'agenzia di intelligence argentina che assiste e coordina permanentemente le funzioni e le operazioni di tutti i servizi di intelligence dell'Esercito.","t":"Central de Reunión de Inteligencia Militar","u":"https://en.wikipedia.org/wiki/Central_de_Reuni%C3%B3n_de_Inteligencia_Militar","d":"2026-11-20","l":"en"},"Q6978366":{"s":"Il National Security Service (NSS) è il servizio di sicurezza interna dell'Armenia, responsabile della sicurezza nazionale e dell'intelligence, e anche della Guardia di frontiera armena; ha sede in Nalbandyan Street a Yerevan.","t":"National Security Service (Armenia)","u":"https://en.wikipedia.org/wiki/National_Security_Service_(Armenia)","d":"2026-11-20","l":"en"},"Q116441410":{"s":"Servizio di intelligence estera dell'Armenia, prevalentemente civile, posto sotto la diretta supervisione dell'Ufficio del Primo ministro, con sede a Yerevan. Istituito nell'ottobre 2023 per sostituire il Servizio di sicurezza nazionale (NSS), erede del KGB sovietico armeno.","t":"Foreign Intelligence Service (Armenia)","u":"https://en.wikipedia.org/wiki/Foreign_Intelligence_Service_(Armenia)","d":"2026-11-20","l":"en"},"Q782740":{"s":"Agenzia australiana di sicurezza interna e intelligence, responsabile della difesa da spionaggio, sabotaggio, terrorismo e ingerenze straniere, con sede a Canberra e uffici in tutti i territori. Non ha poteri di polizia né è armata; è paragonabile all'MI5 britannico.","t":"Australian Security Intelligence Organisation","u":"https://it.wikipedia.org/wiki/Australian_Security_Intelligence_Organisation","d":"2026-11-20","l":"it"},"Q181694":{"s":"Servizio di intelligence estera dell'Australia, che raccoglie informazioni soprattutto tramite human intelligence, dipendente dal Dipartimento degli Affari esteri e del commercio (DFAT) e con sede a Canberra. Formato nel 1952, la sua esistenza è rimasta segreta fino al 1972.","t":"Australian Secret Intelligence Service","u":"https://en.wikipedia.org/wiki/Australian_Secret_Intelligence_Service","d":"2026-11-20","l":"en"},"Q267707":{"s":"Agenzia statutaria australiana per l'intelligence dei segnali, il supporto alle operazioni militari e la cyberguerra, che monitora i segnali in Asia meridionale e orientale nell'ambito dell'alleanza Five Eyes. Istituita nel 1947 come Defence Signals Bureau, ha assunto l'attuale nome nel 2013.","t":"Australian Signals Directorate","u":"https://en.wikipedia.org/wiki/Australian_Signals_Directorate","d":"2026-11-20","l":"en"},"Q5251198":{"s":"Organizzazione australiana per l'intelligence geospaziale, parte del Dipartimento della Difesa, che raccoglie, analizza e distribuisce informazioni geospaziali (GEOINT) a supporto della difesa e degli interessi nazionali. È una delle sei agenzie della Comunità di intelligence australiana.","t":"Australian Geospatial-Intelligence Organisation","u":"https://en.wikipedia.org/wiki/Australian_Geospatial-Intelligence_Organisation","d":"2026-11-20","l":"en"},"Q39071222":{"s":"Agenzia statutaria australiana che fornisce consulenza al Primo ministro e al Comitato per la sicurezza nazionale, produce valutazioni di intelligence da tutte le fonti e coordina la Comunità nazionale di intelligence. Dipende direttamente dal Primo ministro ed è l'equivalente australiano dell'ODNI statunitense.","t":"Office of National Intelligence","u":"https://en.wikipedia.org/wiki/Office_of_National_Intelligence","d":"2026-11-20","l":"en"},"Q3021190":{"s":"Organizzazione di intelligence militare australiana, responsabile di valutazioni strategiche e tecniche su questioni di sicurezza e supporto alle decisioni della Difesa, senza raccogliere intelligence né condurre azioni coperte. Fa parte della Defence Intelligence Group insieme all'AGO.","t":"Defence Intelligence Organisation","u":"https://en.wikipedia.org/wiki/Defence_Intelligence_Organisation","d":"2026-11-20","l":"en"},"Q488079":{"s":"Ufficio di intelligence dell'esercito austriaco, che ricerca informazioni su operazioni e progetti militari all'estero e analizza i dati raccolti. Ha uffici a Linz, Graz e Klagenfurt.","t":"Heeres-Nachrichtenamt","u":"https://en.wikipedia.org/wiki/Heeres-Nachrichtenamt","d":"2026-11-20","l":"en"},"Q105967569":{"s":"Il Directorate State Protection and Intelligence Service (DSN) austriaco è un servizio di sicurezza e intelligence statale che dipende dalla Direzione generale per la sicurezza pubblica del Ministero federale dell'Interno (BMI) ed è succeduto al BVT dal 1° dicembre 2021.","t":"Directorate State Protection and Intelligence Service","u":"https://en.wikipedia.org/wiki/Directorate_State_Protection_and_Intelligence_Service","d":"2026-11-20","l":"en"},"Q25541347":{"s":"Il Servizio di Intelligence Estera dell'Azerbaigian (Xarici Kəşfiyyat Xidməti) è uno dei servizi speciali del Paese, con l'obiettivo di aumentare l'efficacia delle attività dei servizi speciali e migliorare la struttura dell'amministrazione statale.","t":"Foreign Intelligence Service (Azerbaijan)","u":"https://en.wikipedia.org/wiki/Foreign_Intelligence_Service_(Azerbaijan)","d":"2026-11-20","l":"en"},"Q25541335":{"s":"Il Servizio di Sicurezza di Stato (DTX) dell'Azerbaigian, con sede a Baku, è la principale agenzia di intelligence interna e polizia segreta del Paese; istituito con decreto presidenziale n. 706 del 14 dicembre 2015 dalla dissoluzione del Ministero della Sicurezza Nazionale, ha come controparte estera il Servizio di Intelligence Estera.","t":"State Security Service (Azerbaijan)","u":"https://en.wikipedia.org/wiki/State_Security_Service_(Azerbaijan)","d":"2026-11-20","l":"en"},"Q6978325":{"s":"La National Security Agency (NSA) del Bahrein, o Bahrain Intelligence Agency, è un'autorità investigativa e polizia segreta associata ma non formalmente parte del Ministero dell'Interno, costituita nel 2002 con decreto del re Hamad come sostituta della Direzione generale per le indagini di sicurezza di Stato.","t":"National Security Agency (Bahrain)","u":"https://en.wikipedia.org/wiki/National_Security_Agency_(Bahrain)","d":"2026-11-20","l":"en"},"Q3026771":{"s":"La Direzione generale dell'intelligence delle Forze armate (DGFI) del Bangladesh è il servizio di intelligence delle forze armate, responsabile della raccolta, collazione e valutazione di informazioni strategiche e topografiche, e riferisce al proprio Direttore generale sotto l'autorità esecutiva del Primo ministro.","t":"Directorate General of Forces Intelligence","u":"https://en.wikipedia.org/wiki/Directorate_General_of_Forces_Intelligence","d":"2026-11-20","l":"en"},"Q4314874":{"s":"La National Security Intelligence (NSI) del Bangladesh è un'agenzia di intelligence che costituisce l'organizzazione di riferimento del governo per la sicurezza interna, il controspionaggio e le operazioni di intelligence estera, facendo parte della comunità di intelligence del Bangladesh.","t":"National Security Intelligence","u":"https://en.wikipedia.org/wiki/National_Security_Intelligence","d":"2026-11-20","l":"en"},"Q18711550":{"s":"Il Counter Terrorism and Intelligence Bureau (CTIB) del Bangladesh è un ufficio di intelligence clandestino della Direzione generale dell'intelligence delle Forze armate (DGFI), incaricato dell'antiterrorismo e della raccolta di informazioni su minacce interne ed esterne.","t":"Counter Terrorism and Intelligence Bureau","u":"https://en.wikipedia.org/wiki/Counter_Terrorism_and_Intelligence_Bureau","d":"2026-11-20","l":"en"},"Q4431105":{"s":"Lo Special Branch (SB) del Bangladesh è un'agenzia di intelligence della polizia del Bangladesh e membro chiave della comunità di intelligence, responsabile di raccolta, analisi e diffusione di informazioni su sicurezza interna, sviluppi politici, attività estremiste e minacce all'ordine pubblico.","t":"Special Branch (Bangladesh)","u":"https://en.wikipedia.org/wiki/Special_Branch_(Bangladesh)","d":"2026-11-20","l":"en"},"Q28225439":{"s":"Il National Committee for Intelligence Coordination del Bangladesh è il principale organo con cui il Primo ministro gestisce la sicurezza nazionale e coordina le agenzie di intelligence, riunendo quelle civili e militari; è stato istituito sotto Sheikh Hasina.","t":"National Committee for Intelligence Coordination","u":"https://en.wikipedia.org/wiki/National_Committee_for_Intelligence_Coordination","d":"2026-11-20","l":"en"},"Q3511607":{"s":"Il Belgian State Security Service (VSSE) è l'agenzia di intelligence e sicurezza civile del Belgio, dipendente dal Ministero della Giustizia, fondata nel 1830 e considerata il servizio di intelligence più antico del mondo.","t":"State Security Service (Belgium)","u":"https://en.wikipedia.org/wiki/State_Security_Service_(Belgium)","d":"2026-11-20","l":"en"},"Q970334":{"s":"Il Belgian General Information and Security Service (GISS/ADIV/SGRS) è il servizio di intelligence militare del Belgio, dipendente dal Ministro della Difesa e affiancato alla VSSE.","t":"Belgian General Information and Security Service","u":"https://en.wikipedia.org/wiki/Belgian_General_Information_and_Security_Service","d":"2026-11-20","l":"en"},"Q1329608":{"s":"Il KGB della Bielorussia è l'agenzia di intelligence nazionale bielorussa, successore bielorusso del KGB sovietico, che ha mantenuto il nome russo dopo la dissoluzione dell'URSS; la polizia antisommossa è l'OMON.","t":"KGB (Bielorussia)","u":"https://it.wikipedia.org/wiki/KGB_(Bielorussia)","d":"2026-11-20","l":"it"},"Q6043834":{"s":"L'Agenzia d'intelligence e sicurezza della Bosnia ed Erzegovina (OSA-OBA BiH), con sede a Sarajevo, è la principale agenzia di intelligence e sicurezza del Paese, istituita nel marzo 2004 dalle Camere del Parlamento.","t":"Agenzia d'intelligence e sicurezza della Bosnia ed Erzegovina","u":"https://it.wikipedia.org/wiki/Agenzia_d%27intelligence_e_sicurezza_della_Bosnia_ed_Erzegovina","d":"2026-11-20","l":"it"},"Q105320008":{"s":"La Directorate of Intelligence and Security (DIS) del Botswana è l'agenzia di intelligence interna, con compiti di controspionaggio e sicurezza interna, istituita con l'Intelligence and Security Service Act entrato in vigore nel 2008.","t":"Directorate of Intelligence and Security","u":"https://en.wikipedia.org/wiki/Directorate_of_Intelligence_and_Security","d":"2026-11-20","l":"en"},"Q399639":{"s":"L'ABIN è il servizio segreto civile del Brasile, che ha sostituito il Servizio nazionale delle informazioni (SNI) creato a metà degli anni '60 durante il governo militare.","t":"Agência Brasileira de Inteligência","u":"https://it.wikipedia.org/wiki/Ag%C3%AAncia_Brasileira_de_Intelig%C3%AAncia","d":"2026-11-20","l":"it"},"Q10287832":{"s":"Il Gabinete de Segurança Institucional (GSI) è un ufficio esecutivo del governo federale brasiliano che assiste direttamente il Presidente su sicurezza nazionale e politica di difesa.","t":"Institutional Security Bureau","u":"https://en.wikipedia.org/wiki/Institutional_Security_Bureau","d":"2026-11-20","l":"en"},"Q6047728":{"s":"Internal Security Department (Brunei): Servizio di intelligence interna e polizia segreta del Brunei, alle dipendenze dell'Ufficio del Primo Ministro sotto il Sultano; si occupa di questioni criminali e di intelligence, con poteri di detenzione per chi è ritenuto una minaccia alla sicurezza nazionale. Data di nascita non indicata.","t":"Internal Security Department (Brunei)","u":"https://en.wikipedia.org/wiki/Internal_Security_Department_(Brunei)","d":"2026-11-20","l":"en"},"Q12279300":{"s":"State Agency for National Security (Bulgaria): Agenzia specializzata in controspionaggio e sicurezza, incaricata di individuare, prevenire e neutralizzare le minacce alla sicurezza nazionale bulgara; è il servizio di sicurezza più potente del Paese. Data di nascita e dipendenza non indicate.","t":"State Agency for National Security","u":"https://en.wikipedia.org/wiki/State_Agency_for_National_Security","d":"2026-11-20","l":"en"},"Q4314876":{"s":"State Intelligence Agency (Bulgaria): Servizio bulgaro di intelligence estera che raccoglie, elabora e analizza informazioni per la leadership statale in materia di sicurezza nazionale. Data di nascita e dipendenza non indicate.","t":"State Intelligence Agency (Bulgaria)","u":"https://en.wikipedia.org/wiki/State_Intelligence_Agency_(Bulgaria)","d":"2026-11-20","l":"en"},"Q1032405":{"s":"CSIS – Canadian Security Intelligence Service (Canada): Principale servizio di intelligence nazionale del Canada, responsabile della raccolta e analisi di informazioni su minacce alla sicurezza, spionaggio e controspionaggio, in Canada e all'estero. Data di nascita e dipendenza non indicate.","t":"Canadian Security Intelligence Service","u":"https://it.wikipedia.org/wiki/Canadian_Security_Intelligence_Service","d":"2026-11-20","l":"it"},"Q597935":{"s":"Communications Security Establishment Canada (Canada): Agenzia canadese di intelligence crittografica e sicurezza informatica, responsabile dell'intelligence sui segnali esteri e delle operazioni cyber, con supporto tecnico a militari e forze dell'ordine; è un'agenzia autonoma nell'ambito del portafoglio della Difesa nazionale, il cui responsabile risponde al Ministro della Difesa. Data di nascit…","t":"Communications Security Establishment","u":"https://en.wikipedia.org/wiki/Communications_Security_Establishment","d":"2026-11-20","l":"en"},"Q18712149":{"s":"Canadian Forces Intelligence Command (Canada): Organizzazione che centralizza tutte le capacità di raccolta e valutazione dell'intelligence delle Forze armate canadesi. Data di nascita e dipendenza non indicate.","t":"Canadian Forces Intelligence Command","u":"https://en.wikipedia.org/wiki/Canadian_Forces_Intelligence_Command","d":"2026-11-20","l":"en"},"Q56305694":{"s":"Direction générale de service de sécurité des institutions de l'État (Ciad): Servizio di intelligence ciadiano incaricato della sicurezza presidenziale, dell'intelligence militare interna e dell'antiterrorismo, fondato nel 2005 per sostituire la Guardia repubblicana. Dipendenza non indicata.","t":"General Directorate of the Security Services of State Institutions","u":"https://en.wikipedia.org/wiki/General_Directorate_of_the_Security_Services_of_State_Institutions","d":"2026-11-20","l":"en"},"Q56306361":{"s":"Agence nationale de sécurité de l'État (Ciad): Agenzia di intelligence della Repubblica del Ciad, successore della Direzione della documentazione e della sicurezza (DDS) creata dall'ex presidente Hissène Habré; dal 2017 ha poteri di arresto. Dipendenza non indicata.","t":"Agence nationale de sécurité","u":"https://en.wikipedia.org/wiki/Agence_nationale_de_s%C3%A9curit%C3%A9","d":"2026-11-20","l":"en"},"Q3821912":{"s":"L'Agencia Nacional de Inteligencia cilena, creata nel 2004, coordina l'attività di intelligence e consiglia il Presidente; dipende amministrativamente dal Ministero dell'Interno e ha un bilancio di circa 4 milioni di dollari.","t":"Agencia Nacional de Inteligencia","u":"https://en.wikipedia.org/wiki/Agencia_Nacional_de_Inteligencia","d":"2026-11-20","l":"en"},"Q1068951":{"s":"Il Ministero per la sicurezza dello Stato cinese (Guoanbu) svolge funzioni di spionaggio, controspionaggio e polizia segreta, con un forte compito di sorveglianza dei dissidenti; il testo non indica l'anno di creazione.","t":"Ministero per la sicurezza dello Stato (Cina)","u":"https://it.wikipedia.org/wiki/Ministero_per_la_sicurezza_dello_Stato_(Cina)","d":"2026-11-20","l":"it"},"Q2663809":{"s":"L'Intelligence Bureau cinese, organo del Dipartimento Stato Maggiore Congiunto della Commissione militare centrale, è la principale organizzazione di intelligence militare dell'Esercito popolare di liberazione; deriva dal precedente Dipartimento di intelligence dello Stato Maggiore, noto anche come Secondo Dipartimento o 2PLA.","t":"Intelligence Bureau of the Joint Staff Department","u":"https://en.wikipedia.org/wiki/Intelligence_Bureau_of_the_Joint_Staff_Department","d":"2026-11-20","l":"en"},"Q24915366":{"s":"Il Servizio di intelligence di Cipro è l'agenzia nazionale civile di intelligence e sicurezza della Repubblica di Cipro, riorganizzata con legge parlamentare del 14 aprile 2016; fondata nel 1970 dall'arcivescovo Makarios.","t":"Cypriot Intelligence Service","u":"https://en.wikipedia.org/wiki/Cypriot_Intelligence_Service","d":"2026-11-20","l":"en"},"Q19694750":{"s":"La Dirección Nacional de Inteligencia colombiana è la principale agenzia di intelligence del paese, dipende solo dal Presidente e succede al Dipartimento amministrativo di sicurezza (DAS), sciolto nel 2011 dopo vari scandali.","t":"National Intelligence Directorate (Colombia)","u":"https://en.wikipedia.org/wiki/National_Intelligence_Directorate_(Colombia)","d":"2026-11-20","l":"en"},"Q858054":{"s":"Il Dipartimento di sicurezza dello Stato nordcoreano è la polizia segreta del paese, agenzia autonoma che risponde direttamente al leader supremo, coinvolta nei campi di concentramento e in gravi abusi dei diritti umani; il testo non indica l'anno di creazione.","t":"Dipartimento di sicurezza dello Stato","u":"https://it.wikipedia.org/wiki/Dipartimento_di_sicurezza_dello_Stato","d":"2026-11-20","l":"it"},"Q12613368":{"s":"Il Reconnaissance General Bureau nordcoreano, istituito nel 2009 e parte dello Stato Maggiore, gestisce le operazioni clandestine dello Stato e, tramite il Bureau 121, la maggior parte delle capacità cyber del paese; si concentra su Giappone, Corea del Sud e Stati Uniti.","t":"Reconnaissance General Bureau","u":"https://en.wikipedia.org/wiki/Reconnaissance_General_Bureau","d":"2026-11-20","l":"en"},"Q485566":{"s":"Il National Intelligence Service (NIS) è la principale agenzia di intelligence della Corea del Sud; il testo non indica altri dettagli.","t":"National Intelligence Service","u":"https://it.wikipedia.org/wiki/National_Intelligence_Service","d":"2026-11-20","l":"it"},"Q56084716":{"s":"Defense Security Support Command (Corea del Sud): Il testo descrive il Defense Counterintelligence Command (DCC), agenzia di intelligence militare e controspionaggio del Ministero della Difesa sudcoreano, nata come Army Counterintelligence Corps il 21 ottobre 1950.","t":"Defense Counterintelligence Command","u":"https://en.wikipedia.org/wiki/Defense_Counterintelligence_Command","d":"2026-11-20","l":"en"},"Q5205089":{"s":"Defense Intelligence Agency (Corea del Sud): Agenzia di intelligence militare e di supporto al combattimento del Ministero della Difesa sudcoreano, che raccoglie e analizza informazioni globali, gestisce operazioni clandestine, cibersicurezza e guerra psicologica. Il testo non indica l'anno di fondazione.","t":"Defense Intelligence Agency (South Korea)","u":"https://en.wikipedia.org/wiki/Defense_Intelligence_Agency_(South_Korea)","d":"2026-11-20","l":"en"},"Q2600717":{"s":"Security and Intelligence Agency (Croazia): Servizio di sicurezza e intelligence estero del governo croato, che raccoglie analisi e svolge operazioni coperte, fondato nel 2006. Il direttore è nominato dal Presidente e dal Primo Ministro congiuntamente.","t":"Security and Intelligence Agency (Croatia)","u":"https://en.wikipedia.org/wiki/Security_and_Intelligence_Agency_(Croatia)","d":"2026-11-20","l":"en"},"Q3514898":{"s":"Military Security and Intelligence Agency (Croazia): Agenzia di intelligence del Ministero della Difesa e delle Forze Armate croate, con compiti di controspionaggio e operazioni coperte, fondata nel 2006. Il direttore è nominato dal Presidente e dal Primo Ministro congiuntamente.","t":"Military Security and Intelligence Agency (Croatia)","u":"https://en.wikipedia.org/wiki/Military_Security_and_Intelligence_Agency_(Croatia)","d":"2026-11-20","l":"en"},"Q1227421":{"s":"Dirección General de Inteligencia (Cuba): Servizio segreto civile cubano per le operazioni estere, fondato nel 1961 e dipendente dal Ministero dell'Interno, con stretti legami con il KGB. La 5ª Dirección è una sezione per azioni all'estero, la DGCI si occupa di controspionaggio interno.","t":"Dirección General de Inteligencia","u":"https://it.wikipedia.org/wiki/Direcci%C3%B3n_General_de_Inteligencia","d":"2026-11-20","l":"it"},"Q3077736":{"s":"Danish Defence Intelligence Service (Danimarca): Servizio di intelligence estera e militare danese, dipendente dal Ministero della Difesa, che raccoglie e analizza informazioni su politica, finanza, scienza e settore militare. Ha sede al Kastellet di Copenaghen.","t":"Danish Defence Intelligence Service","u":"https://en.wikipedia.org/wiki/Danish_Defence_Intelligence_Service","d":"2026-11-20","l":"en"},"Q3174167":{"s":"Danish Security and Intelligence Service (Danimarca): Servizio nazionale di sicurezza e intelligence danese, che si occupa solo di sicurezza interna, prevenendo e contrastando minacce alla democrazia e alla sicurezza del Paese. Opera come braccio informativo della polizia.","t":"Danish Security and Intelligence Service","u":"https://en.wikipedia.org/wiki/Danish_Security_and_Intelligence_Service","d":"2026-11-20","l":"en"},"Q630014":{"s":"Apparato d'Informazioni Generali (Egitto): Principale servizio segreto egiziano, noto anche come Mukhabaràt, responsabile del controspionaggio interno e autorizzato a operare all'estero.","t":"Apparato d'informazioni generali","u":"https://it.wikipedia.org/wiki/Apparato_d%27informazioni_generali","d":"2026-11-20","l":"it"},"Q5348413":{"s":"Agenzia di Sicurezza Nazionale (Egitto): principale agenzia di sicurezza interna egiziana, con compiti di controspionaggio, sicurezza interna e di frontiera, antiterrorismo e sorveglianza. Dipende dal Ministero dell'Interno, ha sede al Cairo e deriva dal Servizio Investigativo per la Sicurezza dello Stato.","t":"National Security Sector","u":"https://en.wikipedia.org/wiki/National_Security_Sector","d":"2026-11-20","l":"en"},"Q12192542":{"s":"Autorità di Intelligence Militare (Egitto): agenzia di intelligence militare del Ministero della Difesa egiziano, che si occupa di raccolta e analisi informativa, controspionaggio, antiterrorismo e operazioni ibride. Fa parte della comunità dell'intelligence egiziana insieme al Servizio Generale di Intelligence e al Settore di Sicurezza Nazionale.","t":"Military Intelligence Authority","u":"https://en.wikipedia.org/wiki/Military_Intelligence_Authority","d":"2026-11-20","l":"en"},"Q106405876":{"s":"Ufficio per la Sicurezza Nazionale (Eritrea): agenzia di intelligence dell'Eritrea. Il testo non indica altre informazioni su competenze, dipendenza o data di nascita.","t":"National Security Office (Eritrea)","u":"https://en.wikipedia.org/wiki/National_Security_Office_(Eritrea)","d":"2026-11-20","l":"en"},"Q1721811":{"s":"KAPO, Servizio di sicurezza interna (Estonia): servizio centrale di sicurezza nazionale, responsabile della tutela dell'ordine costituzionale, del controspionaggio e di indagini su reati specifici come terrorismo, crimini di guerra e traffico di armi ed esplosivi. Opera sotto il Ministero dell'Interno. Il testo non indica la data di nascita.","t":"Estonian Internal Security Service","u":"https://en.wikipedia.org/wiki/Estonian_Internal_Security_Service","d":"2026-11-20","l":"en"},"Q12376592":{"s":"Välisluureamet, Servizio informazioni estero (Estonia): agenzia civile nazionale di intelligence estera, che raccoglie informazioni su interessi e attività stranieri e le trasmette alle più alte cariche dello Stato e dei ministeri competenti. Dal novembre 2022 il direttore generale è Kaupo Rosin. Il testo non indica la data di nascita.","t":"Estonian Foreign Intelligence Service","u":"https://en.wikipedia.org/wiki/Estonian_Foreign_Intelligence_Service","d":"2026-11-20","l":"en"},"Q61388138":{"s":"Centro di Intelligence Militare delle Forze di Difesa estoni (Estonia): massimo apparato di intelligence e controspionaggio militare, posto sotto il comando strategico dello Stato Maggiore delle Forze di Difesa. Si occupa di raccolta informativa, operazioni clandestine, antiterrorismo militare, valutazione delle minacce e guerra psicologica. Il testo non indica la data di nascita.","t":"Military Intelligence Centre of Estonian Defence Forces","u":"https://en.wikipedia.org/wiki/Military_Intelligence_Centre_of_Estonian_Defence_Forces","d":"2026-11-20","l":"en"},"Q109313036":{"s":"Servizio Nazionale di Intelligence e Sicurezza (Etiopia): il testo è una pagina di disambiguazione che elenca tre servizi omonimi: quello etiope, quello ruandese e quello sudanese, quest'ultimo rinominato Servizio Generale di Intelligence nel 2019. Non fornisce altre informazioni.","t":"National Intelligence and Security Service","u":"https://en.wikipedia.org/wiki/National_Intelligence_and_Security_Service","d":"2026-11-20","l":"en"},"Q108749618":{"s":"Servizio Nazionale di Intelligence e Sicurezza (Etiopia): principale agenzia di intelligence e sicurezza del governo etiope, incaricata di difendere la sicurezza nazionale. Raccoglie, analizza e diffonde informazioni ai decisori, contrasta traffico di droga e armi, cybercrime e criminalità organizzata, e guida la Task Force congiunta per la sicurezza e l'intelligence. Il testo non indica la data…","t":"National Intelligence and Security Service (Ethiopia)","u":"https://en.wikipedia.org/wiki/National_Intelligence_and_Security_Service_(Ethiopia)","d":"2026-11-20","l":"en"},"Q2976464":{"s":"NICA (Filippine): Principale organo filippino di raccolta e analisi intelligence, incaricato di attività overt, covert e clandestine, interne ed estere, e di fornire stime al Presidente e al Consiglio di sicurezza nazionale. Il testo non indica data di nascita né servizio di origine.","t":"National Intelligence Coordinating Agency","u":"https://en.wikipedia.org/wiki/National_Intelligence_Coordinating_Agency","d":"2026-11-20","l":"en"},"Q549972":{"s":"Supo (Finlandia): Forza di polizia e servizio di intelligence per la sicurezza nazionale, con circa 420 dipendenti, impegnato in antiterrorismo, controspionaggio e prevenzione delle minacce interne. Costituito nel 1949 per sostituire la Valpo.","t":"Suojelupoliisi","u":"https://it.wikipedia.org/wiki/Suojelupoliisi","d":"2026-11-20","l":"it"},"Q5450866":{"s":"FDIA (Finlandia): Agenzia di intelligence delle Forze di difesa finlandesi per SIGINT, GEOINT e IMINT, operativa dal 2014. Le sue origini risalgono al 1927 per la radio intelligence e al 1812 per la topografia militare.","t":"Finnish Defence Intelligence Agency","u":"https://en.wikipedia.org/wiki/Finnish_Defence_Intelligence_Agency","d":"2026-11-20","l":"en"},"Q3032398":{"s":"PE TIEDOS (Finlandia): Servizio di intelligence militare del Comando di difesa finlandese, con l'FDIA alle sue dipendenze. Discende dall'Ufficio informazioni creato nel 1918, durante la guerra civile finlandese.","t":"Intelligence Division (Finland)","u":"https://en.wikipedia.org/wiki/Intelligence_Division_(Finland)","d":"2026-11-20","l":"en"},"Q335827":{"s":"DGSE (Francia): Servizio informazioni estero francese, dipendente dal Ministero della difesa, con il compito di tutelare gli interessi francesi all'estero. Diretto dal 26 giugno 2017 da un direttore nominato nel testo. Data di nascita non indicata.","t":"Direction générale de la Sécurité extérieure","u":"https://it.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_de_la_S%C3%A9curit%C3%A9_ext%C3%A9rieure","d":"2026-11-20","l":"it"},"Q167079":{"s":"DGSI (Francia): Servizio informazioni interno francese, dipendente dal Ministero dell'interno e branca della Polizia nazionale. Creato il 1º luglio 2008 dalla fusione di DST (1907) e RG (1944).","t":"Direction centrale du renseignement intérieur","u":"https://it.wikipedia.org/wiki/Direction_centrale_du_renseignement_int%C3%A9rieur","d":"2026-11-20","l":"it"},"Q3029491":{"s":"DRSD (Francia): Agenzia di sicurezza del Ministero della difesa francese, che si occupa di controspionaggio, antiterrorismo e protezione di informazioni e strutture sensibili. Subentrò all'ex agenzia di sicurezza militare nel 1981.","t":"Direction de la Protection et de la Sécurité de la Défense","u":"https://it.wikipedia.org/wiki/Direction_de_la_Protection_et_de_la_S%C3%A9curit%C3%A9_de_la_D%C3%A9fense","d":"2026-11-20","l":"it"},"Q3029599":{"s":"DNRED (Francia): Servizio di intelligence doganale francese, fondato il 1º marzo 1988, dedicato al contrasto dei grandi traffici internazionali di contrabbando. Nel 2009 ha creato l'unità Cyberdouane contro il traffico online.","t":"Direction nationale du renseignement et des enquêtes douanières","u":"https://en.wikipedia.org/wiki/Direction_nationale_du_renseignement_et_des_enqu%C3%AAtes_douani%C3%A8res","d":"2026-11-20","l":"en"},"Q335814":{"s":"La DRM è il servizio di informazione militare francese, creato nel 1992 per raccogliere e centralizzare le informazioni militari per le forze armate; riferisce direttamente al Capo di stato maggiore e al Presidente della Repubblica.","t":"Direction du renseignement militaire","u":"https://en.wikipedia.org/wiki/Direction_du_renseignement_militaire","d":"2026-11-20","l":"en"},"Q665682":{"s":"Il SIS (State Intelligence Services) è il servizio di intelligence del Gambia, fondato nel 1994 dopo il colpo di stato militare guidato da Yahya Jammeh, già National Intelligence Agency (NIA).","t":"State Intelligence Services (The Gambia)","u":"https://en.wikipedia.org/wiki/State_Intelligence_Services_(The_Gambia)","d":"2026-11-20","l":"en"},"Q21659239":{"s":"Il SSSG è il servizio di sicurezza statale della Georgia, sotto l'autorità del Governo, che tutela l'ordine costituzionale, la sovranità e l'integrità territoriale del Paese, contrasta terrorismo, criminalità organizzata e corruzione e protegge i segreti di Stato.","t":"State Security Service of Georgia","u":"https://en.wikipedia.org/wiki/State_Security_Service_of_Georgia","d":"2026-11-20","l":"en"},"Q272969":{"s":"Il BND è il servizio federale di intelligence tedesco, con sede a Berlino, unico responsabile della ricognizione civile e militare all'estero; è direttamente subordinato alla Cancelleria federale e impiega circa 6.500 dipendenti.","t":"Bundesnachrichtendienst","u":"https://it.wikipedia.org/wiki/Bundesnachrichtendienst","d":"2026-11-20","l":"it"},"Q310522":{"s":"Il BfV è l'ufficio federale tedesco per la protezione della Costituzione, che sorveglia sul territorio nazionale le attività contrarie alla Legge fondamentale; dipende dal Ministro federale degli Interni e si basa sulla legge del 20 dicembre 1990.","t":"Bundesamt für Verfassungsschutz","u":"https://it.wikipedia.org/wiki/Bundesamt_f%C3%BCr_Verfassungsschutz","d":"2026-11-20","l":"it"},"Q480220":{"s":"Il MAD è il servizio di informazione e controspionaggio militare tedesco, parte della Bundeswehr, con sede a Colonia e uffici regionali nelle città tedesche; conta circa 1.300 collaboratori tra militari e civili.","t":"Militärischer Abschirmdienst","u":"https://it.wikipedia.org/wiki/Milit%C3%A4rischer_Abschirmdienst","d":"2026-11-20","l":"it"},"Q1358063":{"s":"Il CIRO era l'agenzia civile di intelligence giapponese presso il Segretariato del Gabinetto, che raccoglieva e analizzava informazioni a livello mondiale e riferiva direttamente al Primo Ministro; il 31 luglio 2026 è stato sostituito dal National Intelligence Bureau.","t":"Cabinet Intelligence and Research Office","u":"https://en.wikipedia.org/wiki/Cabinet_Intelligence_and_Research_Office","d":"2026-11-20","l":"en"},"Q1346667":{"s":"La PSIA è l'agenzia di intelligence nazionale giapponese, amministrata dal Ministero della Giustizia, che si occupa di sicurezza interna e spionaggio contro le minacce alla sicurezza nazionale ai sensi della Legge sulla prevenzione delle attività sovversive.","t":"Agenzia d'informazione per la pubblica sicurezza","u":"https://it.wikipedia.org/wiki/Agenzia_d%27informazione_per_la_pubblica_sicurezza","d":"2026-11-20","l":"it"},"Q2915133":{"s":"Il Quartier generale per le informazioni della difesa giapponese è un'agenzia di intelligence militare e di intelligence dei segnali dipendente dal Ministero della Difesa, modellata sulla Defense Intelligence Agency statunitense.","t":"Defense Intelligence Headquarters","u":"https://en.wikipedia.org/wiki/Defense_Intelligence_Headquarters","d":"2026-11-20","l":"en"},"Q140598198":{"s":"La National Intelligence Bureau giapponese, istituita il 31 luglio 2026 in base alla legge approvata dalla Dieta, è governata dal National Intelligence Council presieduto dal primo ministro e sostituisce l'Ufficio di ricerca e intelligence del Gabinetto come principale agenzia informativa.","t":"National Intelligence Bureau (Japan)","u":"https://en.wikipedia.org/wiki/National_Intelligence_Bureau_(Japan)","d":"2026-11-20","l":"en"},"Q140005422":{"s":"Il National Intelligence Council giapponese è il principale organo con cui il primo ministro e il Gabinetto coordinano le politiche di intelligence, e governa la National Intelligence Bureau; la sua istituzione ha suscitato critiche per possibili violazioni della privacy e per il rischio di un ritorno al militarismo.","t":"National Intelligence Council (Japan)","u":"https://en.wikipedia.org/wiki/National_Intelligence_Council_(Japan)","d":"2026-11-20","l":"en"},"Q773865":{"s":"La Dairat al-Mukhabarat al-Ammah è il servizio di intelligence giordano, creato nel 1952, che opera nel Vicino Oriente e collabora con Regno Unito e Stati Uniti; di recente il re Abdullah II ne ha sostituito il vertice con il generale Fayṣal al-Shūbakī.","t":"Da'irat al-Mukhabarat al-Amma","u":"https://it.wikipedia.org/wiki/Da%27irat_al-Mukhabarat_al-Amma","d":"2026-11-20","l":"it"},"Q303976":{"s":"Il Servizio nazionale per l'informazione (EYP) greco, con sede ad Atene, è la principale branca dei servizi segreti della Grecia, istituita con la legge 1645 del 1986 e subordinata al ministro per l'ordine pubblico; accanto ad essa anche il Ministero degli Affari Esteri dispone di una propria struttura informativa.","t":"Servizi segreti greci","u":"https://it.wikipedia.org/wiki/Servizi_segreti_greci","d":"2026-11-20","l":"it"},"Q16934074":{"s":"Il Service d'Intelligence National haitiano era un'agenzia di intelligence creata dalla CIA dopo la caduta di Jean-Claude Duvalier nel 1986, composta da ufficiali delle Forze armate; impiegata nel narcotraffico e nella violenza politica, fu coinvolta nel massacro di elettori nel 1987.","t":"Service d'Intelligence National","u":"https://en.wikipedia.org/wiki/Service_d%27Intelligence_National","d":"2026-11-20","l":"en"},"Q2092054":{"s":"Il Research and Analysis Wing (R&AW) è l'agenzia di intelligence estera dell'India, incaricata di raccogliere e valutare informazioni fuori dai confini nazionali; opera come ala del Segretariato del Gabinetto, con un proprio capo che riferisce al primo ministro tramite il Cabinet Secretary e il consigliere per la sicurezza nazionale.","t":"Research & Analysis Wing","u":"https://en.wikipedia.org/wiki/Research_%26_Analysis_Wing","d":"2026-11-20","l":"en"},"Q2426814":{"s":"L'Intelligence Bureau (IB) indiano è l'agenzia per la sicurezza interna e il controspionaggio, dipendente dal Ministero dell'Interno; fondato nel 1887 come Central Special Branch, è considerato il più antico servizio di intelligence esistente. Dal 1968 si occupa principalmente di intelligence interna, e dal giugno 2026 è diretto da Mahesh Dixit.","t":"Intelligence Bureau (India)","u":"https://en.wikipedia.org/wiki/Intelligence_Bureau_(India)","d":"2026-11-20","l":"en"},"Q6978857":{"s":"Organizzazione tecnica di ricerca nazionale indiana, un'agenzia di intelligence tecnica istituita nel 2004 e che riferisce al Consigliere per la sicurezza nazionale e all'Ufficio del Primo ministro; comprende anche un centro per la protezione delle infrastrutture informative critiche e un istituto di ricerca sulla crittografia.","t":"National Technical Research Organisation","u":"https://en.wikipedia.org/wiki/National_Technical_Research_Organisation","d":"2026-11-20","l":"en"},"Q17051525":{"s":"Agenzia di intelligence per la difesa indiana, un'organizzazione di intelligence militare interforze istituita nel 2002 per coordinare l'intelligence di difesa di Esercito, Marina e Aeronautica, operante nell'ambito dello Stato Maggiore Integrato del Ministero della Difesa.","t":"Defence Intelligence Agency (India)","u":"https://en.wikipedia.org/wiki/Defence_Intelligence_Agency_(India)","d":"2026-11-20","l":"en"},"Q2619338":{"s":"Badan Intelijen Negara (BIN), principale agenzia di intelligence indonesiana, precedentemente nota come Bakin fino al 2001; è responsabile del coordinamento dello scambio di informazioni tra l'Indonesia e le altre agenzie di intelligence.","t":"Badan Intelijen Nasional","u":"https://it.wikipedia.org/wiki/Badan_Intelijen_Nasional","d":"2026-11-20","l":"it"},"Q12473188":{"s":"Agenzia di intelligence strategica delle Forze armate indonesiane (BAIS TNI), che si occupa specificamente di intelligence militare sotto il comando del quartier generale delle Forze armate e analizza scenari di breve, medio e lungo termine per il Comandante e per il Ministero della Difesa.","t":"Indonesian Strategic Intelligence Agency","u":"https://en.wikipedia.org/wiki/Indonesian_Strategic_Intelligence_Agency","d":"2026-11-20","l":"en"},"Q1365657":{"s":"Ministero dell'Intelligence iraniano (VEVAK), principale organizzazione di intelligence dell'Iran, finanziata con importanti sovvenzioni governative; fondato il 18 agosto 1984 come successore della SAVAK, ma il testo non ne descrive chiaramente i confini.","t":"Ministero delle informazioni e della sicurezza nazionale","u":"https://it.wikipedia.org/wiki/Ministero_delle_informazioni_e_della_sicurezza_nazionale","d":"2026-11-20","l":"it"},"Q2917152":{"s":"Servizio di intelligence nazionale iracheno (INIS), agenzia di intelligence civile incaricata di raccogliere informazioni, valutare le minacce alla sicurezza nazionale e consigliare il governo; soggetta al controllo parlamentare e riferisce direttamente al Primo ministro, è stata creata con l'aiuto della CIA per sostituire il Mukhabarat.","t":"Iraqi National Intelligence Service","u":"https://en.wikipedia.org/wiki/Iraqi_National_Intelligence_Service","d":"2026-11-20","l":"en"},"Q85850825":{"s":"Cellula di intelligence dei Falcons (FIC), braccio operativo dell'Agenzia federale per l'intelligence e le indagini del Ministero dell'Interno iracheno, addestrata da CIA e MI6, che secondo il testo ha condotto centinaia di operazioni contro militanti.","t":"Falcons Intelligence Cell","u":"https://en.wikipedia.org/wiki/Falcons_Intelligence_Cell","d":"2026-11-20","l":"en"},"Q3799334":{"s":"Direzione dell'intelligence delle Forze di difesa irlandesi (Stiúrthóireacht na Faisnéise, G2), agenzia nazionale di intelligence della Repubblica d'Irlanda, sezione delle forze armate irlandesi.","t":"Stiúrthóireacht na Faisnéise","u":"https://it.wikipedia.org/wiki/Sti%C3%BArth%C3%B3ireacht_na_Faisn%C3%A9ise","d":"2026-11-20","l":"it"},"Q34216":{"s":"Mossad: servizio di intelligence israeliano per le operazioni all'estero, parte della comunità dei servizi segreti di Israele.","t":"Mossad","u":"https://it.wikipedia.org/wiki/Mossad","d":"2026-11-20","l":"it"},"Q380238":{"s":"Shin Bet (Shabak): servizio di sicurezza interna israeliano, subordinato direttamente al Primo ministro; fondato nel periodo post-bellico (dato non presente nel testo).","t":"Shin Bet","u":"https://it.wikipedia.org/wiki/Shin_Bet","d":"2026-11-20","l":"it"},"Q453558":{"s":"Aman: servizio centrale di intelligence militare delle Forze di difesa israeliane, componente autonomo della comunità dei servizi segreti israeliani.","t":"Direttorato dell'Intelligence militare","u":"https://it.wikipedia.org/wiki/Direttorato_dell%27Intelligence_militare","d":"2026-11-20","l":"it"},"Q392910":{"s":"AISE: servizio segreto italiano per l'estero, parte del Sistema di informazione per la sicurezza della Repubblica, con compiti di intelligence al di fuori del territorio nazionale.","t":"Agenzia informazioni e sicurezza esterna","u":"https://it.wikipedia.org/wiki/Agenzia_informazioni_e_sicurezza_esterna","d":"2026-11-20","l":"it"},"Q1227126":{"s":"DIS: dipartimento della Presidenza del Consiglio dei ministri, istituito dalla legge 3 agosto 2007, n. 124, che coordina la ricerca informativa e la programmazione delle attività di AISE e AISI.","t":"Dipartimento delle informazioni per la sicurezza","u":"https://it.wikipedia.org/wiki/Dipartimento_delle_informazioni_per_la_sicurezza","d":"2026-11-20","l":"it"},"Q392916":{"s":"AISI: organizzazione di investigazione informativa per la sicurezza interna della Repubblica Italiana, con compiti di informazione, sicurezza e controspionaggio sul territorio nazionale.","t":"Agenzia informazioni e sicurezza interna","u":"https://it.wikipedia.org/wiki/Agenzia_informazioni_e_sicurezza_interna","d":"2026-11-20","l":"it"},"Q1054300":{"s":"Centro intelligence interforze (C.I.I.): struttura di intelligence del II Reparto dello Stato Maggiore della Difesa, istituita nel 1997 e operativa dal 2000, con funzioni di servizio segreto tecnico-militare delle Forze armate italiane.","t":"Centro intelligence interforze","u":"https://it.wikipedia.org/wiki/Centro_intelligence_interforze","d":"2026-11-20","l":"it"},"Q3962187":{"s":"Sistema di informazione per la sicurezza della Repubblica: insieme di organi e autorità che assicurano le attività informative per salvaguardare la Repubblica Italiana da minacce interne ed esterne, introdotto dalla legge 3 agosto 2007, n. 124.","t":"Sistema di informazione per la sicurezza della Repubblica","u":"https://it.wikipedia.org/wiki/Sistema_di_informazione_per_la_sicurezza_della_Repubblica","d":"2026-11-20","l":"it"},"Q422091":{"s":"Il Comitato per la Sicurezza Nazionale del Kazakistan, istituito il 13 luglio 1992, è un'agenzia di intelligence che gestisce il Servizio di frontiera e supervisiona l'unità di commando Arystan.","t":"National Security Committee (Kazakhstan)","u":"https://en.wikipedia.org/wiki/National_Security_Committee_(Kazakhstan)","d":"2026-11-20","l":"en"},"Q119333":{"s":"Il Servizio di informazione estera del Comitato per la Sicurezza Nazionale del Kazakistan è un'agenzia statale che tutela la sovranità del paese; è membro della comunità informativa kazaka, insieme all'intelligence estera del Ministero della Difesa.","t":"Foreign Intelligence Service (Kazakhstan)","u":"https://en.wikipedia.org/wiki/Foreign_Intelligence_Service_(Kazakhstan)","d":"2026-11-20","l":"en"},"Q15911311":{"s":"Il Servizio Informazioni Nazionale del Kenya (NIS), noto come NSIS fino al 1999, è l'agenzia di intelligence interna ed estera del paese; le sue origini risalgono allo \"Special Branch\", creato nel 1952 sotto l'amministrazione britannica.","t":"National Intelligence Service (Kenya)","u":"https://en.wikipedia.org/wiki/National_Intelligence_Service_(Kenya)","d":"2026-11-20","l":"en"},"Q1962513":{"s":"L'Agenzia di Intelligence del Kosovo (KIA) è un'agenzia civile di intelligence che fornisce informazioni sulla sicurezza nazionale ai vertici politici del Kosovo.","t":"Kosovo Intelligence Agency","u":"https://en.wikipedia.org/wiki/Kosovo_Intelligence_Agency","d":"2026-11-20","l":"en"},"Q20560178":{"s":"Il Servizio di Sicurezza di Stato della Lettonia (VDD) è il servizio civile di controspionaggio e sicurezza interna; è l'unico dei tre servizi lettoni autorizzato a condurre indagini preliminari e a detenere persone.","t":"State Security Service (Latvia)","u":"https://en.wikipedia.org/wiki/State_Security_Service_(Latvia)","d":"2026-11-20","l":"en"},"Q3161571":{"s":"La Direzione generale della Sicurezza generale del Libano, fondata il 21 luglio 1921 come \"primo ufficio\", è un'agenzia di intelligence che dipende dal ministro dell'Interno ed è guidata da un direttore generale.","t":"General Directorate of General Security","u":"https://en.wikipedia.org/wiki/General_Directorate_of_General_Security","d":"2026-11-20","l":"en"},"Q6510941":{"s":"La Sicurezza di Stato libanese (Amn Eddawla), istituita nel 1985, è l'agenzia civile di sicurezza interna del Libano; raccoglie e analizza informazioni, svolge operazioni clandestine e risponde direttamente al Presidente e al Primo ministro.","t":"Lebanese State Security","u":"https://en.wikipedia.org/wiki/Lebanese_State_Security","d":"2026-11-20","l":"en"},"Q55624806":{"s":"La National Security Agency della Liberia è il principale apparato civile di intelligence e sicurezza del paese, posto sotto l'autorità diretta del Presidente; svolge operazioni clandestine, monitoraggio informativo globale e attività di contrasto al terrorismo e all'insorgenza.","t":"National Security Agency (Liberia)","u":"https://en.wikipedia.org/wiki/National_Security_Agency_(Liberia)","d":"2026-11-20","l":"en"},"Q9206059":{"s":"Il Dipartimento per la sicurezza dello Stato (VSD) è l'agenzia civile nazionale di intelligence e sicurezza della Lituania, che raccoglie e analizza informazioni sulle minacce interne ed esterne alla sicurezza nazionale e lavora per eliminarle.","t":"State Security Department of Lithuania","u":"https://en.wikipedia.org/wiki/State_Security_Department_of_Lithuania","d":"2026-11-20","l":"en"},"Q1474802":{"s":"Il Servizio di Intelligence dello Stato (SREL) è l'agenzia di intelligence interna del Lussemburgo, soprannominata in lussemburghese \"Spëtzeldéngscht\" (Servizio spie).","t":"Service de Renseignement de l'État","u":"https://en.wikipedia.org/wiki/Service_de_Renseignement_de_l%27%C3%89tat","d":"2026-11-20","l":"en"},"Q31360590":{"s":"L'Agenzia di Intelligence della Repubblica di Macedonia del Nord è l'agenzia civile nazionale di intelligence e sicurezza, istituita come organo separato dell'amministrazione statale con la legge del aprile 1995.","t":"Intelligence Agency of North Macedonia","u":"https://en.wikipedia.org/wiki/Intelligence_Agency_of_North_Macedonia","d":"2026-11-20","l":"en"},"Q17511898":{"s":"Il Servizio militare per la sicurezza e l'intelligence è il servizio nazionale di intelligence e sicurezza militare della Macedonia del Nord, inserito nell'ambito del Ministero della Difesa.","t":"Military Service for Security and Intelligence","u":"https://en.wikipedia.org/wiki/Military_Service_for_Security_and_Intelligence","d":"2026-11-20","l":"en"},"Q1784185":{"s":"Il Royal Intelligence Corps (Kor Risik DiRaja) è un'agenzia di intelligence malese specializzata in raccolta e analisi di informazioni, guerra psicologica, sorveglianza, spionaggio, ricognizione e controspionaggio, e gestisce anche la propaganda e la controprpaganda dell'Esercito malese.","t":"Royal Intelligence Corps","u":"https://en.wikipedia.org/wiki/Royal_Intelligence_Corps","d":"2026-11-20","l":"en"},"Q5251270":{"s":"L'Organizzazione di intelligence della difesa malese (MDIO) è l'agenzia di intelligence militare delle Forze armate malesi, guidata da un tenente generale dell'esercito e composta dai rami di intelligence di esercito, marina e aeronautica.","t":"Malaysian Defence Intelligence Organisation","u":"https://en.wikipedia.org/wiki/Malaysian_Defence_Intelligence_Organisation","d":"2026-11-20","l":"en"},"Q687114":{"s":"La Direzione generale della sorveglianza del territorio (DGST) è il servizio civile di intelligence interna del Marocco, incaricato del monitoraggio e dell'anticipazione di attività interne potenzialmente sovversive. Dal 2005 è diretta da Abdellatif Hammouchi, che dirige anche la polizia nazionale.","t":"General Directorate for Territorial Surveillance","u":"https://en.wikipedia.org/wiki/General_Directorate_for_Territorial_Surveillance","d":"2026-11-20","l":"en"},"Q2917372":{"s":"La Direzione generale degli studi e della documentazione (DGED) è l'agenzia di intelligence estera del Marocco, posta sotto l'autorità dell'Amministrazione per la difesa nazionale, incaricata della sicurezza nazionale e della tutela delle istituzioni. Collabora spesso con la DGST e con servizi internazionali.","t":"General Directorate of Studies and Documentation","u":"https://en.wikipedia.org/wiki/General_Directorate_of_Studies_and_Documentation","d":"2026-11-20","l":"en"},"Q59488384":{"s":"Il Centro Nacional de Inteligencia (CNI) messicano è il principale servizio civile di intelligence del Paese, amministrato dalla Segreteria di Sicurezza e Protezione Cittadina; è nato nel dicembre 2018 sostituendo il CISEN.","t":"National Intelligence Centre (Mexico)","u":"https://en.wikipedia.org/wiki/National_Intelligence_Centre_(Mexico)","d":"2026-11-20","l":"en"},"Q2576279":{"s":"Il Serviciul de Informații și Securitate (SIS) della Repubblica di Moldavia è un organismo statale che garantisce la sicurezza nazionale con misure di intelligence e controspionaggio, operando sul territorio nazionale e all'estero.","t":"Security and Intelligence Service of Moldova","u":"https://en.wikipedia.org/wiki/Security_and_Intelligence_Service_of_Moldova","d":"2026-11-20","l":"en"},"Q3759481":{"s":"La General Intelligence Agency of Mongolia (GIA), amministrata dal primo ministro, ha sede a Ulan Bator e raccoglie e valuta informazioni su terrorismo, criminalità organizzata, traffico di armi e droga, riciclaggio e immigrazione clandestina.","t":"General Intelligence Agency of Mongolia","u":"https://it.wikipedia.org/wiki/General_Intelligence_Agency_of_Mongolia","d":"2026-11-20","l":"it"},"Q2826630":{"s":"L'Agencija za Nacionalnu Bezbjednost (ANB) del Montenegro è l'agenzia nazionale di intelligence, con sede a Podgorica, incaricata di raccogliere e analizzare informazioni su minacce alla sicurezza, terrorismo, criminalità organizzata e difesa.","t":"National Security Agency (Montenegro)","u":"https://en.wikipedia.org/wiki/National_Security_Agency_(Montenegro)","d":"2026-11-20","l":"en"},"Q6857685":{"s":"L'Ufficio del Capo della Sicurezza Militare (OCMSA), noto come Sa Ya Pha, è il principale apparato di intelligence militare delle Forze Armate del Myanmar (Tatmadaw), con compiti di operazioni coperte, controinsurrezione e controspionaggio militare.","t":"Office of the Chief of Military Security Affairs","u":"https://en.wikipedia.org/wiki/Office_of_the_Chief_of_Military_Security_Affairs","d":"2026-11-20","l":"en"},"Q86666241":{"s":"Il Namibia Central Intelligence Service (NCIS) è l'agenzia governativa responsabile di tutti i servizi di intelligence della Namibia, istituita nel giugno 1998 in base alla Proclamation 12/1998 e guidata da un direttore generale.","t":"Namibia Central Intelligence Service","u":"https://en.wikipedia.org/wiki/Namibia_Central_Intelligence_Service","d":"2026-11-20","l":"en"},"Q3336899":{"s":"La National Intelligence Agency (NIA) della Nigeria è una divisione governativa incaricata di supervisionare le operazioni di intelligence estera e di controspionaggio.","t":"National Intelligence Agency (Nigeria)","u":"https://en.wikipedia.org/wiki/National_Intelligence_Agency_(Nigeria)","d":"2026-11-20","l":"en"},"Q1708058":{"s":"Lo State Security Service (SSS), autodefinitosi Department of State Services (DSS), è un'agenzia di sicurezza nigeriana dipendente dalla Presidenza, nata come una delle tre organizzazioni successrici della National Security Organization (NSO), con sede ad Abuja.","t":"State Security Service (Nigeria)","u":"https://en.wikipedia.org/wiki/State_Security_Service_(Nigeria)","d":"2026-11-20","l":"en"},"Q5251207":{"s":"Servizio di intelligence militare della Nigeria, istituito nel 1986 per fornire intelligence militare alle Forze Armate e al Ministero della Difesa; guidato dal Chief of Defence Intelligence, nominato dal Presidente nigeriano.","t":"Defence Intelligence Agency (Nigeria)","u":"https://en.wikipedia.org/wiki/Defence_Intelligence_Agency_(Nigeria)","d":"2026-11-20","l":"en"},"Q3077732":{"s":"Servizio di intelligence militare norvegese, dipendente dal Capo della Difesa e dal Ministero della Difesa; il testo non indica l'anno di nascita.","t":"Norwegian Intelligence Service","u":"https://en.wikipedia.org/wiki/Norwegian_Intelligence_Service","d":"2026-11-20","l":"en"},"Q3175066":{"s":"Servizio di sicurezza della polizia norvegese (PST), precedentemente chiamato POT; il cambio di nome è stato deciso dal Parlamento il 2 giugno 2001. Il testo non indica l'anno di nascita.","t":"Norwegian Police Security Service","u":"https://en.wikipedia.org/wiki/Norwegian_Police_Security_Service","d":"2026-11-20","l":"en"},"Q1769906":{"s":"Autorità norvegese per la sicurezza nazionale (NSM), istituita il 1° gennaio 2003 come successore di Forsvarets sikkerhetsstab; si occupa di sicurezza preventiva, sicurezza ICT e analisi delle minacce.","t":"National Security Authority (Norway)","u":"https://en.wikipedia.org/wiki/National_Security_Authority_(Norway)","d":"2026-11-20","l":"en"},"Q1195581":{"s":"Principale servizio di intelligence nazionale della Nuova Zelanda, competente per sicurezza nazionale e intelligence estera; dipende dal Direttore Generale, dal Ministro e dalla commissione parlamentare. Istituito il 28 novembre 1956, originariamente contro lo spionaggio sovietico.","t":"New Zealand Security Intelligence Service","u":"https://en.wikipedia.org/wiki/New_Zealand_Security_Intelligence_Service","d":"2026-11-20","l":"en"},"Q382463":{"s":"Dipartimento della pubblica amministrazione neozelandese che raccoglie e analizza informazioni di intelligence per la sicurezza nazionale; considerato il servizio più potente del Paese e l'equivalente del GCHQ britannico o della NSA. Il testo non indica l'anno di nascita.","t":"Government Communications Security Bureau","u":"https://en.wikipedia.org/wiki/Government_Communications_Security_Bureau","d":"2026-11-20","l":"en"},"Q2896938":{"s":"Agenzia di analisi dell'intelligence neozelandese all'interno del Dipartimento del Primo Ministro e del Gabinetto (DPMC), che fornisce valutazioni al Primo Ministro, ai Ministri e alle missioni diplomatiche. Il testo non indica l'anno di nascita.","t":"National Assessments Bureau","u":"https://en.wikipedia.org/wiki/National_Assessments_Bureau","d":"2026-11-20","l":"en"},"Q16999282":{"s":"Servizio di sicurezza nazionale dell'Oman, competente solo per la sicurezza interna e la lotta al terrorismo; l'intelligence estera è gestita dal Palace Office. Il testo non indica l'anno di nascita.","t":"Internal Security Service","u":"https://en.wikipedia.org/wiki/Internal_Security_Service","d":"2026-11-20","l":"en"},"Q1866011":{"s":"AIVD: Servizio generale di intelligence e sicurezza dei Paesi Bassi, con compiti di intelligence interna, estera e sui segnali e di tutela della sicurezza nazionale; collabora con i Five Eyes. Il servizio militare corrispondente è il MIVD, dipendente dal Ministero della Difesa.","t":"General Intelligence and Security Service","u":"https://en.wikipedia.org/wiki/General_Intelligence_and_Security_Service","d":"2026-11-20","l":"en"},"Q274564":{"s":"ISI: La più importante delle tre branche dei servizi di intelligence del Pakistan, dipendente dalle forze armate, fondata nel 1948 per coordinare le attività dei servizi segreti militari. Il testo la descrive come uno «Stato nello Stato» e ne riporta l'origine in Sir Robert Cawthome, ex maggiore generale dell'esercito indiano britannico.","t":"Inter-Services Intelligence","u":"https://it.wikipedia.org/wiki/Inter-Services_Intelligence","d":"2026-11-20","l":"it"},"Q3153003":{"s":"IB: Principale agenzia di sicurezza civile del Pakistan, sotto il controllo amministrativo dell'Ufficio del Primo Ministro, responsabile di sicurezza interna, antiterrorismo e controspionaggio. Fondata nel 1947, affonda le radici nel Thuggee and Dacoity Department del 1830 dell'epoca coloniale.","t":"Intelligence Bureau (Pakistan)","u":"https://en.wikipedia.org/wiki/Intelligence_Bureau_(Pakistan)","d":"2026-11-20","l":"en"},"Q4114378":{"s":"Military Intelligence del Pakistan: Servizio di intelligence dell'Esercito pakistano (CMI, detto MI), che valuta le capacità delle nazioni rivali e raccoglie informazioni su cellule dormienti, agenti stranieri ed elementi antistatali, incluso lo spionaggio militare.","t":"Military Intelligence (Pakistan)","u":"https://en.wikipedia.org/wiki/Military_Intelligence_(Pakistan)","d":"2026-11-20","l":"en"},"Q6981849":{"s":"Naval Intelligence del Pakistan: Servizio di intelligence della Marina pakistana (NI), che valuta le capacità delle marine straniere e si occupa di tutela delle risorse marittime e di minacce in mare. Le sue attività sono poco pubblicizzate.","t":"Naval Intelligence (Pakistan)","u":"https://en.wikipedia.org/wiki/Naval_Intelligence_(Pakistan)","d":"2026-11-20","l":"en"},"Q4698039":{"s":"Air Intelligence del Pakistan: Servizio di intelligence dell'Aeronautica pakistana (DGAI), con sede a Islamabad e fondato nel 1948. Elabora il quadro informativo aereo, gestisce unità di analisi fotografica e studio dei nuovi velivoli, e collabora con MI, NI e ISI.","t":"Air Intelligence (Pakistan)","u":"https://en.wikipedia.org/wiki/Air_Intelligence_(Pakistan)","d":"2026-11-20","l":"en"},"Q195034":{"s":"Servizio di sicurezza preventiva (Palestina): Apparato di sicurezza interna dell'Autorità Nazionale Palestinese, istituito nel 1994 in base agli accordi di Oslo e dipendente dal Ministero degli Interni. Svolge compiti di sicurezza interna e prevenzione dei crimini, con funzioni simili a una polizia politica; dopo il 2007 opera solo in Cisgiordania.","t":"Servizio di sicurezza preventiva","u":"https://it.wikipedia.org/wiki/Servizio_di_sicurezza_preventiva","d":"2026-11-20","l":"it"},"Q6744376":{"s":"Palestinian General Intelligence Service: Agenzia di intelligence e sicurezza interna dello Stato di Palestina, fondata nel 1994, che opera sotto la supervisione del presidente, il quale ne nomina il direttore. Raccoglie e analizza informazioni su minacce alla sicurezza, indaga sui crimini e mantiene l'ordine nei territori palestinesi.","t":"General Intelligence Service (Palestine)","u":"https://en.wikipedia.org/wiki/General_Intelligence_Service_(Palestine)","d":"2026-11-20","l":"en"},"Q89029333":{"s":"Il PMIS (Palestina) è uno dei principali servizi di sicurezza dello Stato di Palestina, istituito nel 1994 con la nascita dell'Autorità Nazionale Palestinese; si occupa di intelligence militare.","t":"Military Intelligence (Palestine)","u":"https://en.wikipedia.org/wiki/Military_Intelligence_(Palestine)","d":"2026-11-20","l":"en"},"Q28507267":{"s":"La DINI (Perù) è la principale agenzia di intelligence del Perù, responsabile dell'intelligence nazionale, militare e di polizia, nonché del controspionaggio.","t":"National Directorate of Intelligence (Peru)","u":"https://en.wikipedia.org/wiki/National_Directorate_of_Intelligence_(Peru)","d":"2026-11-20","l":"en"},"Q392540":{"s":"L'ABW (Polonia) protegge la sicurezza interna da terrorismo, spionaggio, traffico di droga e armi, criminalità organizzata, corruzione e coercizione economica; il capo riporta direttamente al Primo ministro.","t":"Agencja Bezpieczeństwa Wewnętrznego","u":"https://it.wikipedia.org/wiki/Agencja_Bezpiecze%C5%84stwa_Wewn%C4%99trznego","d":"2026-11-20","l":"it"},"Q601940":{"s":"L'AW (Polonia) raccoglie informazioni estere, pubbliche o segrete, per la sicurezza dello Stato; nata nel 2002 dalla suddivisione dell'Urząd Ochrony Państwa.","t":"Agencja Wywiadu","u":"https://it.wikipedia.org/wiki/Agencja_Wywiadu","d":"2026-11-20","l":"it"},"Q600742":{"s":"La SKW (Polonia) è uno dei servizi segreti polacchi, dedicato al controspionaggio militare.","t":"Służba Kontrwywiadu Wojskowego","u":"https://it.wikipedia.org/wiki/S%C5%82u%C5%BCba_Kontrwywiadu_Wojskowego","d":"2026-11-20","l":"it"},"Q600773":{"s":"La SWW (Polonia) è uno dei servizi segreti polacchi, dedicato allo spionaggio militare.","t":"Służba Wywiadu Wojskowego","u":"https://it.wikipedia.org/wiki/S%C5%82u%C5%BCba_Wywiadu_Wojskowego","d":"2026-11-20","l":"it"},"Q3480562":{"s":"Il SIS (Portogallo) è il servizio portoghese di sicurezza e intelligence, fondato nel 1984, che garantisce la sicurezza interna contro terrorismo, spionaggio, sabotaggio e attacchi informatici.","t":"Serviço de Informações de Segurança","u":"https://en.wikipedia.org/wiki/Servi%C3%A7o_de_Informa%C3%A7%C3%B5es_de_Seguran%C3%A7a","d":"2026-11-20","l":"en"},"Q2274374":{"s":"Il SIED (Portogallo) è il servizio portoghese di intelligence strategica estera per la difesa, che tutela l'indipendenza nazionale, gli interessi nazionali e la sicurezza esterna dello Stato; fa parte del SIRP insieme al SIS.","t":"Serviço de Informações Estratégicas de Defesa","u":"https://en.wikipedia.org/wiki/Servi%C3%A7o_de_Informa%C3%A7%C3%B5es_Estrat%C3%A9gicas_de_Defesa","d":"2026-11-20","l":"en"},"Q1518932":{"s":"Il SIRP è la struttura di coordinamento dell'intelligence portoghese, da cui dipendono il SIS (sicurezza interna) e il SIED (informazioni estere e strategiche di difesa); il testo non indica la data di nascita.","t":"Sistema de Informações da República Portuguesa","u":"https://en.wikipedia.org/wiki/Sistema_de_Informa%C3%A7%C3%B5es_da_Rep%C3%BAblica_Portuguesa","d":"2026-11-20","l":"en"},"Q7267122":{"s":"Qatar State Security è l'agenzia di intelligence statale del Qatar, descritta come organizzazione indipendente; il testo non indica data di nascita, dipendenza né servizio di origine.","t":"Qatar State Security","u":"https://en.wikipedia.org/wiki/Qatar_State_Security","d":"2026-11-20","l":"en"},"Q392509":{"s":"L'ANR è un'agenzia governativa della Repubblica Democratica del Congo incaricata della sicurezza interna ed esterna, criticata da varie organizzazioni per il mancato rispetto dei diritti umani; il testo non indica data di nascita né dipendenza.","t":"Agence nationale de renseignements (Democratic Republic of the Congo)","u":"https://en.wikipedia.org/wiki/Agence_nationale_de_renseignements_(Democratic_Republic_of_the_Congo)","d":"2026-11-20","l":"en"},"Q184560":{"s":"Il SIS, noto come MI6, è l'agenzia di spionaggio estero britannica; dipende dall'Ufficio per gli Esteri ed è sotto la direzione formale del Joint Intelligence Committee; il testo non indica la data di nascita.","t":"Secret Intelligence Service","u":"https://it.wikipedia.org/wiki/Secret_Intelligence_Service","d":"2026-11-20","l":"it"},"Q210175":{"s":"Il MI5 (Security Service) è l'ente britannico per la sicurezza interna e il controspionaggio, con sede a Thames House dal 1995; dipende dall'Home Office ed è sotto la direzione formale del JIC.","t":"MI5","u":"https://it.wikipedia.org/wiki/MI5","d":"2026-11-20","l":"it"},"Q220798":{"s":"Il GCHQ, con sede principale a Cheltenham, è l'agenzia britannica per la sicurezza, lo spionaggio e il controspionaggio nel campo delle comunicazioni (SIGINT); il testo non indica data di nascita né dipendenza.","t":"Government Communications Headquarters","u":"https://it.wikipedia.org/wiki/Government_Communications_Headquarters","d":"2026-11-20","l":"it"},"Q352160":{"s":"La Defence Intelligence è l'organizzazione britannica di intelligence militare che si occupa di analisi \"all-source\" a supporto delle operazioni e della politica di difesa; fa parte integrante del Ministero della Difesa, è finanziata nel bilancio della difesa e si chiamava Defence Intelligence Staff fino al 2009.","t":"Defence Intelligence","u":"https://en.wikipedia.org/wiki/Defence_Intelligence","d":"2026-11-20","l":"en"},"Q14644105":{"s":"La Joint Intelligence Organisation è l'agenzia britannica responsabile delle valutazioni di intelligence e dello sviluppo della capacità analitica della comunità; è guidata da un funzionario di livello Permanent Secretary e supporta il JIC e il National Security Council con valutazioni per ministri e alti funzionari.","t":"Joint Intelligence Organisation (United Kingdom)","u":"https://en.wikipedia.org/wiki/Joint_Intelligence_Organisation_(United_Kingdom)","d":"2026-11-20","l":"en"},"Q121548153":{"s":"Il Defence Intelligence Fusion Centre (Regno Unito), con sede a RAF Wyton, supporta la pianificazione della Difesa, le operazioni correnti e il processo di valutazione intelligence, con un ruolo ormai oltre l'imagery intelligence. Fa parte del Joint Forces Intelligence Group nell'ambito di Defence Intelligence; deriva dal National Imagery Exploitation Centre (ex JARIC) e risale alle ricognizioni…","t":"Defence Intelligence Fusion Centre","u":"https://en.wikipedia.org/wiki/Defence_Intelligence_Fusion_Centre","d":"2026-11-20","l":"en"},"Q854461":{"s":"Il BIS (Repubblica Ceca), principale servizio di intelligence interna, raccoglie e analizza informazioni sulle minacce alla sicurezza nazionale e svolge operazioni in patria e all'estero. Dipende direttamente dal Governo, dal Primo Ministro e dal Presidente ed è sottoposto al controllo della Commissione permanente della Camera dei deputati; la sede è a Stodůlky, Praga 5.","t":"Security Information Service","u":"https://en.wikipedia.org/wiki/Security_Information_Service","d":"2026-11-20","l":"en"},"Q330666":{"s":"L'ÚZSI (Repubblica Ceca), principale servizio di intelligence estera, raccoglie, analizza e diffonde informazioni a sostegno della politica estera ed economica e contro terrorismo, proliferazione di armi di distruzione di massa e crimini economici. Opera in base alla legge n. 153/1994 Coll. e riferisce al Governo ceco.","t":"Office for Foreign Relations and Information","u":"https://en.wikipedia.org/wiki/Office_for_Foreign_Relations_and_Information","d":"2026-11-20","l":"en"},"Q123694":{"s":"Military Intelligence (Repubblica Ceca), servizio di intelligence militare (VZ), svolge attività di IMINT, HUMINT, SIGINT e OSINT, concentrandosi sulle \"regioni di crisi\" come Balcani, Medio Oriente, Afghanistan-Pakistan, CSI e Africa. Non viene indicata la data di nascita né il servizio da cui deriva.","t":"Military Intelligence (Czech Republic)","u":"https://en.wikipedia.org/wiki/Military_Intelligence_(Czech_Republic)","d":"2026-11-20","l":"en"},"Q390342":{"s":"Il Serviciul de Informaţii Externe (SIE, Romania) è uno dei servizi segreti rumeni, specializzato nell'intelligence estera su questioni di sicurezza nazionale, come definito dalla legge 1/1998. Opera secondo la Costituzione, le leggi, le decisioni del Consiglio Supremo di Difesa (CSAT) e i regolamenti militari; le sue attività sono coperte dal segreto di Stato. Non viene indicata la data di nasci…","t":"Serviciul de Informații Externe","u":"https://it.wikipedia.org/wiki/Serviciul_de_Informa%C8%9Bii_Externe","d":"2026-11-20","l":"it"},"Q1426649":{"s":"L'SRI (Romania), istituito il 26 marzo 1990, è uno dei servizi segreti rumeni che raccoglie informazioni esclusivamente sul territorio nazionale e le trasmette alle istituzioni competenti, tra cui governo, Presidente e agenzie ministeriali. Utilizza SIGINT, OSINT e HUMINT.","t":"Serviciul Român de Informații","u":"https://it.wikipedia.org/wiki/Serviciul_Rom%C3%A2n_de_Informa%C8%9Bii","d":"2026-11-20","l":"it"},"Q5280730":{"s":"La DGIA (Romania), Direzione generale di intelligence della Difesa, è l'agenzia di intelligence militare delle Forze Armate rumene, posta sotto il Ministero della Difesa Nazionale. È organizzata in due direzioni (informazioni militari e contrinformazione e sicurezza militare), un Detașamentul Special de Protecție și Intervenție, un centro radioelettronico, un centro NATO HUMINT, un centro di adde…","t":"General Directorate for Defense Intelligence","u":"https://en.wikipedia.org/wiki/General_Directorate_for_Defense_Intelligence","d":"2026-11-20","l":"en"},"Q5280729":{"s":"La DGPI (Romania), Direzione generale di protezione interna, è l'agenzia di intelligence criminale del Ministero dell'Interno rumeno, creata in seguito allo scioglimento dell'UM 0215. Ha il compito di individuare rischi, minacce e vulnerabilità nell'ambito del Ministero, per far rispettare la legge e tutelare lo Stato di diritto e la democrazia.","t":"Direcția Generală de Protecție Internă","u":"https://en.wikipedia.org/wiki/Direc%C8%9Bia_General%C4%83_de_Protec%C8%9Bie_Intern%C4%83","d":"2026-11-20","l":"en"},"Q124496260":{"s":"Agenzia ruandese per l'intelligence e la sicurezza nazionale, creata nel 1994 dalla Repubblica del Ruanda dopo il genocidio ruandese; il testo non indica da chi dipende.","t":"National Intelligence and Security Service (Rwanda)","u":"https://en.wikipedia.org/wiki/National_Intelligence_and_Security_Service_(Rwanda)","d":"2026-11-20","l":"en"},"Q58792":{"s":"Servizio federale di sicurezza della Federazione Russa (FSB), agenzia speciale federale per la sicurezza interna; nata nel 1995 dalla riorganizzazione dell'FSK (1991-1995), per decreto firmato da Boris El'cin; sede a Mosca.","t":"Federal'naja služba bezopasnosti","u":"https://it.wikipedia.org/wiki/Federal%27naja_slu%C5%BEba_bezopasnosti","d":"2026-11-20","l":"it"},"Q115782":{"s":"Direzione generale per le informazioni militari (GRU), servizio di intelligence delle Forze armate russe (e sovietiche fino al 1991), con compiti anche di guardia di frontiera; dipende dallo Stato maggiore delle Forze armate; fondato nel 1918.","t":"Glavnoe razvedyvatel'noe upravlenie","u":"https://it.wikipedia.org/wiki/Glavnoe_razvedyvatel%27noe_upravlenie","d":"2026-11-20","l":"it"},"Q863254":{"s":"Servizio informazioni estero (SVR) della Federazione Russa, uno dei tre servizi segreti russi, competente per la sicurezza e il contrasto alle minacce provenienti da o verso l'estero; il testo non indica da chi dipende né quando è nato.","t":"Služba vnešnej razvedki","u":"https://it.wikipedia.org/wiki/Slu%C5%BEba_vne%C5%A1nej_razvedki","d":"2026-11-20","l":"it"},"Q853456":{"s":"Agenzia di sicurezza e intelligence serba, competente per la sicurezza nazionale, la raccolta di intelligence e il controspionaggio; fondata nel 2002 dopo la soppressione del Direttorato per la Sicurezza dello Stato, che segue una tradizione iniziata nel 1899.","t":"Agenzia di Sicurezza e Intelligence","u":"https://it.wikipedia.org/wiki/Agenzia_di_Sicurezza_e_Intelligence","d":"2026-11-20","l":"it"},"Q6852167":{"s":"Agenzia serba di sicurezza militare e controspionaggio, unità organizzativa del Ministero della Difesa; il testo non indica quando è nata né da quale servizio derivi.","t":"Military Security Agency","u":"https://en.wikipedia.org/wiki/Military_Security_Agency","d":"2026-11-20","l":"en"},"Q7939852":{"s":"Agenzia serba di intelligence militare, unità organizzativa del Ministero della Difesa, incaricata di fornire informazioni militari e di tutelare gli interessi militari della Serbia all'estero; il testo non indica quando è nata né da quale servizio derivi.","t":"Military Intelligence Agency","u":"https://en.wikipedia.org/wiki/Military_Intelligence_Agency","d":"2026-11-20","l":"en"},"Q1112557":{"s":"Principale agenzia di sicurezza e servizio di intelligence interna di Singapore, competente per il controspionaggio, il contrasto al terrorismo e all'estremismo e la protezione della sicurezza nazionale; il testo non indica da chi dipende né quando è nata.","t":"Internal Security Department (Singapore)","u":"https://en.wikipedia.org/wiki/Internal_Security_Department_(Singapore)","d":"2026-11-20","l":"en"},"Q11016557":{"s":"Il Security and Intelligence Division (SID) è il servizio di intelligence estera di Singapore, dipendente dal Ministero della Difesa (MINDEF), incaricato di raccogliere, elaborare e analizzare informazioni globali sulla sicurezza nazionale.","t":"Security and Intelligence Division","u":"https://en.wikipedia.org/wiki/Security_and_Intelligence_Division","d":"2026-11-20","l":"en"},"Q2980822":{"s":"Il Slovenská informačná služba (SIS) è l'agenzia di intelligence slovacca, istituita il 15 febbraio 1993 come erede del servizio di informazione interna della Cecoslovacchia, con modello integrato che copre intelligence interna ed estera; l'intelligence militare è esclusa.","t":"Slovenská informačná služba","u":"https://en.wikipedia.org/wiki/Slovensk%C3%A1_informa%C4%8Dn%C3%A1_slu%C5%BEba","d":"2026-11-20","l":"en"},"Q7071375":{"s":"Il Národný bezpečnostný úrad (NBÚ) è l'organo statale slovacco per la protezione delle informazioni classificate, del servizio crittografico e della firma elettronica, istituito il 1° novembre 2001 e controllato da una commissione parlamentare speciale.","t":"National Security Bureau (Slovakia)","u":"https://en.wikipedia.org/wiki/National_Security_Bureau_(Slovakia)","d":"2026-11-20","l":"en"},"Q16520017":{"s":"Il Vojenské spravodajstvo è l'agenzia di intelligence militare slovacca, dipendente dal Ministero della Difesa, nata il 1° gennaio 2013 dalla fusione di VSS e VOS.","t":"Vojenské spravodajstvo","u":"https://en.wikipedia.org/wiki/Vojensk%C3%A9_spravodajstvo","d":"2026-11-20","l":"en"},"Q3442610":{"s":"Il SOVA (Slovenska obveščevalno-varnostna agencija) è il principale servizio civile di intelligence e sicurezza della Slovenia, subordinato direttamente al Primo Ministro; il suo corrispettivo militare è l'OVS, parte del Ministero della Difesa.","t":"Slovenian Intelligence and Security Agency","u":"https://en.wikipedia.org/wiki/Slovenian_Intelligence_and_Security_Agency","d":"2026-11-20","l":"en"},"Q17068877":{"s":"La NISA (National Intelligence and Security Agency) è l'agenzia di intelligence nazionale della Repubblica federale di Somalia, responsabile di intelligence, operazioni segrete e tutela della sicurezza dello Stato.","t":"National Intelligence and Security Agency","u":"https://it.wikipedia.org/wiki/National_Intelligence_and_Security_Agency","d":"2026-11-20","l":"it"},"Q916449":{"s":"Il CNI (Centro Nacional de Inteligencia) è il servizio segreto del Regno di Spagna, creato con la riforma del sistema di intelligence spagnolo del 2002.","t":"Centro Nacional de Inteligencia","u":"https://it.wikipedia.org/wiki/Centro_Nacional_de_Inteligencia","d":"2026-11-20","l":"it"},"Q5761825":{"s":"Il CIFAS (Centro de Inteligencia de las Fuerzas Armadas) è un'agenzia di intelligence spagnola parte dello Stato Maggiore della Difesa (EMAD), istituita nel 2004 e che sostituisce la precedente Divisione Intelligence dello Stato Maggiore.","t":"Spanish Armed Forces Intelligence Center","u":"https://en.wikipedia.org/wiki/Spanish_Armed_Forces_Intelligence_Center","d":"2026-11-20","l":"en"},"Q23000922":{"s":"Il Dipartimento di Sicurezza Nazionale spagnolo è un organo di staff consultivo dell'Ufficio del Primo Ministro su temi di sicurezza nazionale e membro permanente del Consiglio di Sicurezza Nazionale; è stato creato nel 2012 con il Regio Decreto 1119/2012.","t":"Department of National Security (Spain)","u":"https://en.wikipedia.org/wiki/Department_of_National_Security_(Spain)","d":"2026-11-20","l":"en"},"Q8348474":{"s":"La Comisaría General de Información (CGI) è un servizio di intelligence interno al Corpo Nazionale di Polizia spagnolo, responsabile della raccolta, analisi e diffusione di informazioni per la sicurezza interna, soprattutto in materia di antiterrorismo.","t":"General Commissariat of Information","u":"https://en.wikipedia.org/wiki/General_Commissariat_of_Information","d":"2026-11-20","l":"en"},"Q111306752":{"s":"Il Servizio Informazioni della Guardia Civil spagnola (SIGC) è un servizio di intelligence interno alla Guardia Civil, con compiti di raccolta, analisi e diffusione di informazioni per la sicurezza interna, soprattutto contro il terrorismo.","t":"Civil Guard Information Service","u":"https://en.wikipedia.org/wiki/Civil_Guard_Information_Service","d":"2026-11-20","l":"en"},"Q6852060":{"s":"Il Military Intelligence Corps (MIC) è un corpo dell'Esercito dello Sri Lanka che svolge operazioni clandestine e coperte, intelligence militare, controspionaggio, cyberwarfare, HUMINT e SIGINT.","t":"Military Intelligence Corps (Sri Lanka)","u":"https://en.wikipedia.org/wiki/Military_Intelligence_Corps_(Sri_Lanka)","d":"2026-11-20","l":"en"},"Q7603530":{"s":"La State Security Agency (SSA) è il dipartimento del governo sudafricano responsabile delle operazioni di intelligence civile; creata nell'ottobre 2009 accorpando agenzie precedenti, risponde politicamente al Ministro della Presidenza.","t":"State Security Agency (South Africa)","u":"https://en.wikipedia.org/wiki/State_Security_Agency_(South_Africa)","d":"2026-11-20","l":"en"},"Q7565746":{"s":"La Divisione Intelligence della Forza di Difesa Nazionale sudafricana (SANDF-ID) è la principale agenzia di intelligence militare del Sudafrica, istituita il 27 aprile 1994.","t":"Defence Intelligence Division (SANDF)","u":"https://en.wikipedia.org/wiki/Defence_Intelligence_Division_(SANDF)","d":"2026-11-20","l":"en"},"Q12206318":{"s":"Il General Intelligence Service (GIS) è il servizio di intelligence del governo federale sudanese, creato nel luglio 2019 dal precedente NISS, in risposta alle richieste dei manifestanti; in passato è stato centrale per la sopravvivenza del regime e la sorveglianza interna.","t":"General Intelligence Service (Sudan)","u":"https://en.wikipedia.org/wiki/General_Intelligence_Service_(Sudan)","d":"2026-11-20","l":"en"},"Q1331110":{"s":"La Säkerhetspolisen (SÄPO), polizia di sicurezza svedese, già Rikspolisstyrelsens säkerhetsavdelning fino al 1989, si occupa di controspionaggio, antiterrorismo, tutela della Costituzione e di soggetti sensibili; l'intelligence militare è affidata al MUST o ad agenzie separate.","t":"Säkerhetspolisen","u":"https://it.wikipedia.org/wiki/S%C3%A4kerhetspolisen","d":"2026-11-20","l":"it"}};
